  if (cos > 0.99) return 'stufen';
  if (cos < -0.99) {
    const towards = (b, A, B) => b[0] * (B.x - A.x) + b[1] * (B.y - A.y) > 0;
    return towards(b1, S1, S2) && towards(b2, S2, S1) ? 'wechsel' : 'outer';
  }
