    const desc = cols.map((c, i) => `${sectors[i]} ${sectors[i] === 1 ? 'Feld' : 'Felder'} ${c}`).join(', ');
    const repeated = cols.flatMap((c, i) => new Array(Math.min(sectors[i], 2)).fill(c));
