/** Sentence part: „$\frac{3}{8}$ (= 0,375 = 37,5 %)“. */
const probText = f => `$${probTex(f)}$${probAlt(f)}`;
/** Result line for keys: the LAST math segment is the exact probability (the worksheet key checker reads it). */
