  odd: { adj: () => 'ungerade', text: () => 'eine ungerade Zahl', build: n => stepList(1, n, 2), test: x => x % 2 === 1 },
  gt: { adj: a => `größer als ${a}`, text: a => `eine Zahl größer als ${a}`, build: (n, a) => stepList(a + 1, n, 1), test: (x, a) => x > a },
