  if (new Set(skills).size !== skills.length) errors.push('Ein Thema ist doppelt gewählt.');
  if (skills.length > WORKSHEET_LIMITS.maxSkills) errors.push(`Höchstens ${WORKSHEET_LIMITS.maxSkills} Themen.`);
